package com.zenix.musicplayer;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

final class FeatureSettingsFormat {
    static final String[] PARTS={"space","playbackPreferences","assistant","networkPolicy"};
    static JSONObject assistant(JSONObject raw){if(raw==null)raw=new JSONObject();JSONObject result=Json.obj("size",120,"locked",false,"music",true,"reduced",false,"fps",12,"hidden",false);for(String key:List.of("locked","music","reduced","hidden"))if(raw.opt(key) instanceof Boolean)Json.put(result,key,raw.optBoolean(key));for(String key:List.of("size","fps"))if(raw.opt(key) instanceof Number){double number=raw.optDouble(key);if(Double.isFinite(number))Json.put(result,key,Math.max(key.equals("size")?64:1,Math.min(key.equals("size")?220:30,Math.round(number))));}return result;}
    static JSONObject clean(JSONObject raw)throws Exception{
        if(raw==null)raw=new JSONObject();if(raw.has("schema")&&(!(raw.opt("schema") instanceof Number)||raw.optDouble("schema")!=1))throw new Exception("功能设置备份来自较新规范，请先更新");if(raw.toString().getBytes(StandardCharsets.UTF_8).length>4*1024*1024)throw new Exception("功能设置备份超过4 MiB");JSONObject presence=new JSONObject(),declared=raw.optJSONObject("present"),policy=new JSONObject(),original=raw.optJSONObject("networkPolicy");
        for(String key:PARTS)Json.put(presence,key,declared!=null&&declared.opt(key) instanceof Boolean?declared.optBoolean(key):raw.has(key));
        for(String category:List.of("audio","lyrics","artwork","preload")){String mode=original==null?"always":original.optString(category,"always");Json.put(policy,category,Set.of("always","unmetered","never").contains(mode)?mode:"always");}
        if(!presence.optBoolean("networkPolicy"))for(String category:List.of("audio","lyrics","artwork","preload"))Json.put(policy,category,"always");return Json.obj("schema",1,"present",presence,"space",SpaceFeatureFormat.clean(presence.optBoolean("space")?raw.optJSONObject("space"):null),"playbackPreferences",PlaybackPreferences.clean(presence.optBoolean("playbackPreferences")?raw.optJSONObject("playbackPreferences"):null),"assistant",assistant(presence.optBoolean("assistant")?raw.optJSONObject("assistant"):null),"networkPolicy",policy);
    }
    static JSONObject merge(JSONObject before,JSONObject incoming,boolean replace)throws Exception{
        JSONObject current=clean(before),other=clean(incoming),next=Json.copy(current);for(String part:PARTS){if(!other.getJSONObject("present").optBoolean(part))continue;
            if(replace||!current.getJSONObject("present").optBoolean(part))Json.put(next,part,other.getJSONObject(part));
            else if(part.equals("space")){JSONObject target=next.getJSONObject("space"),source=other.getJSONObject("space");for(String kind:List.of("bookmarks","zones")){JSONArray rows=target.getJSONArray(kind),addition=source.getJSONArray(kind);Set<String> ids=new HashSet<>();for(int i=0;i<rows.length();i++)ids.add(rows.getJSONObject(i).getString("id"));for(int i=0;i<addition.length();i++)if(ids.add(addition.getJSONObject(i).getString("id")))rows.put(addition.get(i));if(rows.length()>(kind.equals("bookmarks")?30:20))throw new Exception("合并后空间项目过多，请先整理空间或选择使用备份设置");}}
            else if(part.equals("playbackPreferences")){JSONObject target=next.getJSONObject(part),source=other.getJSONObject(part),choices=Json.copy(source.getJSONObject("choices")),local=current.getJSONObject(part).getJSONObject("choices");for(Iterator<String> keys=local.keys();keys.hasNext();){String key=keys.next();Json.put(choices,key,local.opt(key));}if(choices.length()>2000)throw new Exception("合并后单曲偏好超过2000条");Json.put(target,"choices",choices);JSONObject excluded=source.optJSONObject("excluded")==null?new JSONObject():Json.copy(source.getJSONObject("excluded")),saved=current.getJSONObject(part).optJSONObject("excluded");if(saved!=null)for(Iterator<String> keys=saved.keys();keys.hasNext();){String key=keys.next();JSONArray values=excluded.optJSONArray(key);if(values==null)values=new JSONArray();Set<String> seen=new HashSet<>();for(int i=0;i<values.length();i++)seen.add(values.optString(i));JSONArray localRows=saved.getJSONArray(key);for(int i=0;i<localRows.length();i++)if(seen.add(localRows.optString(i)))values.put(localRows.get(i));Json.put(excluded,key,values);}if(excluded.length()>0)Json.put(target,"excluded",excluded);}
            Json.put(next.getJSONObject("present"),part,true);
        }Json.put(next.getJSONObject("space"),"revision",current.getJSONObject("space").optLong("revision")+1);return clean(next);
    }
    static JSONArray diff(JSONObject before,JSONObject incoming)throws Exception{JSONObject current=clean(before),other=clean(incoming);JSONArray result=new JSONArray();String[] labels={"空间书签、分区与漫游","版本偏好","助手显示设置","网络使用偏好"};for(int i=0;i<PARTS.length;i++){String key=PARTS[i];if(other.getJSONObject("present").optBoolean(key))result.put(Json.obj("key",key,"label",labels[i],"status",!current.getJSONObject("present").optBoolean(key)?"新增":BackupFormat.canonical(current.getJSONObject(key)).equals(BackupFormat.canonical(other.getJSONObject(key)))?"相同":"存在差异"));}return result;}
    static JSONObject renderer(JSONObject settings)throws Exception{JSONObject cleaned=clean(settings);JSONObject present=cleaned.getJSONObject("present");present.remove("networkPolicy");cleaned.remove("networkPolicy");return cleaned;}
}
